WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, device, browser, started_at, country, is_new_session, session_no FROM islands ORDER BY id ASC NULLS LAST;
